css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .serie-cajas{display: flex; gap: 4px; flex-wrap: nowrap; font-size: 16px; font-weight: 700; margin-bottom: 5px;}
.mz .serie-cajas .caja-num{width: 50px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; flex-shrink: 0;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .entre-fila{display: flex; gap: 8px; align-items: center; margin-bottom: 4px; font-size: 17px; font-weight: 700;}
.mz .entre-fila .caja-num{width: 42px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .entre-fila .caja-num.vacia{background: #fff;}
